"PlaceId="..tostring(game.PlaceId),
"AutoAttack="..tostring(_G.AutoClicker).." Reach="..tostring(settings.Reach).." ToolHitbox="..tostring(settings.ToolHitbox),
"구조 진단입니다. 서버의 실제 타격 범위는 이 보고서만으로 확정할 수 없습니다."}
local
function
add(v)
lines[#lines+1]=v
end
local
function
read(o,k)
local
ok,v=pcall(function()
return
o[k]
end)
if
not
ok
then
return
"<unavailable>"
end
return
tostring(v):gsub("[\r\n]"," "):sub(1,180)
end
local
function
path(o)
local
ok,v=pcall(function()
return
o:GetFullName()
end)
return
ok
and
v
or
tostring(o)
end
local
function
props(o,keys)
local
out={}
for
_,k
in
ipairs(keys)
do
out[#out+1]=k.."="..read(o,k)
end
add(table.concat(out," | "))
end
