add("--- Extended equipment structure diagnostic 2 ---")
local
function
inspectRoot(root,title,limit)
add("ROOT "..title.."="..(root
and
path(root)
or
"<missing>"))
if
not
root
then
return
end
local
items=root:GetDescendants()
table.sort(items,function(a,b)
return
path(a)<path(b)
end)
add("descendants="..#items.."; scan limit="..limit)
for
i,o
in
ipairs(items)
do
if
i>limit
then
add("... scan limit reached");break
end
if
o:IsA("Model")
or
o:IsA("Tool")
or
o:IsA("Folder")
or
o:IsA("BasePart")
or
o:IsA("JointInstance")
or
o:IsA("WeldConstraint")
or
o:IsA("Attachment")
or
o:IsA("LuaSourceContainer")
or
o:IsA("RemoteEvent")
or
o:IsA("RemoteFunction")
or
o:IsA("ValueBase")
then
add("["..o.ClassName.."] "..path(o))
if
o:IsA("BasePart")
then
props(o,{"Size","Transparency","CanTouch","CanQuery"})
end
if
o:IsA("JointInstance")
or
o:IsA("WeldConstraint")
then
local
function
linked(k)
local
ok,v=pcall(function()
return
o[k]
end)
return
ok
and
v
and
path(v)
or
"<none>"
end
add("Part0="..linked("Part0").." | Part1="..linked("Part1"))
end
if
o:IsA("Tool")
then
props(o,{"Enabled","RequiresHandle","ManualActivationOnly"})
end
if
o:IsA("ValueBase")
then
props(o,{"Value"})
end
local
good,attrs=pcall(function()
return
o:GetAttributes()
end)
if
good
then
local
keys={};for
k
in
pairs(attrs)
do
keys[#keys+1]=k
end;table.sort(keys)
for
n,k
in
ipairs(keys)
do
if
n>12
then
break
end
add("attribute "..k.."="..tostring(attrs[k]):gsub("[\r\n]"," "):sub(1,120))
end
end
end
end
end
inspectRoot(char,"LocalPlayer.Character",350)
