left,
top
=
math.max(0,
left
-
2),
math.max(0,
top
-
2)
right,
bottom
=
math.min(viewport.X,
right
+
2),
math.min(viewport.Y,
bottom
+
2)
return
Vector2.new(math.floor(left),
math.floor(top)),
Vector2.new(math.max(1,
math.ceil(right
-
left)),
math.max(1,
math.ceil(bottom
-
top)))
end
 
