local
function
applyFogRemoval()
Lighting.FogStart
=
9e9
Lighting.FogEnd
=
9e9
for
_,
v
in
ipairs(Lighting:GetChildren())
do
if
v:IsA("Atmosphere")
then
v.Density
=
0
v.Haze
=
0
end
end
end
