function
restoreFog()
if
not
fogBackup
then
return
end
Lighting.FogStart
=
fogBackup.FogStart
Lighting.FogEnd
=
fogBackup.FogEnd
for
atmos,
values
in
pairs(fogBackup.Atmospheres)
do
if
atmos.Parent
then
atmos.Density
=
values.Density
atmos.Haze
=
values.Haze
end
end
fogBackup
=
nil
end
