local
ConfigTab
=
Window:CreateTab("Config",
4483362458)
local
ROOT_DIR
=
"KoreanHubConfigs"
local
PROFILE_DIR
=
ROOT_DIR
..
"/Profiles"
local
fsReady
=
writefile
and
readfile
and
listfiles
and
isfolder
and
makefolder
and
delfile
and
isfile
local
function
ensureFolders()
if
not
isfolder(ROOT_DIR)
then
makefolder(ROOT_DIR)
end
if
not
isfolder(PROFILE_DIR)
then
makefolder(PROFILE_DIR)
end
end
local
function
listProfiles()
if
not
fsReady
then
return
{}
end
ensureFolders()
local
names
=
{}
for
_,
path
in
ipairs(listfiles(PROFILE_DIR))
do
local
name
=
path:match("([^/\\]+)%.json$")
if
name
then
table.insert(names,
name)
end
end
table.sort(names)
return
names
end
local
function
serializeFlags()
local
data
=
{}
for
flag,
el
in
pairs(Rayfield.Flags)
do
if
el.Type
==
"ColorPicker"
then
local
c
=
el.Color
if
typeof(c)
==
"Color3"
then
data[flag]
=
{R
=
c.R,
G
=
c.G,
B
=
c.B}
end
elseif
el.Type
==
"Dropdown"
then
data[flag]
=
el.CurrentOption
elseif
el.CurrentValue
~=
nil
then
data[flag]
=
el.CurrentValue
end
end
return
HttpService:JSONEncode(data)
end
local
function
applyFlags(data)
local
applied
=
0
for
flag,
value
in
pairs(data)
do
local
el
=
Rayfield.Flags[flag]
if
el
then
local
ok
=
pcall(function()
if
el.Type
==
"ColorPicker"
and
type(value)
==
"table"
then
el:Set(Color3.new(value.R,
value.G,
value.B))
else
el:Set(value)
end
end)
if
ok
then
applied
=
applied
+
1
end
end
end
return
applied
end
